import { readerBooks } from "./reader-catalog.js";

const authorProfiles = {
    "affonso-celso": { name: "Affonso Celso", bio: "Affonso Celso de Assis Figueiredo foi escritor, professor, jornalista e político brasileiro. Sua produção atravessa a vida pública e a literatura do fim do Império e das primeiras décadas republicanas.", context: "Seu trabalho ajuda a observar como patriotismo, memória nacional e participação política se encontraram na cultura brasileira da virada do século XIX para o XX." },
    "aluisio-azevedo": { name: "Aluísio Azevedo", bio: "Aluísio Azevedo foi romancista, contista, caricaturista e diplomata maranhense. Tornou-se um dos principais nomes do Naturalismo no Brasil, movimento interessado nas pressões sociais e materiais sobre a vida cotidiana.", context: "A leitura de seus romances permite discutir urbanização, trabalho, desigualdade e os limites das teorias deterministas que marcaram a literatura de seu tempo." },
    "augusto-dos-anjos": { name: "Augusto dos Anjos", bio: "Augusto dos Anjos foi um poeta paraibano cuja obra combina vocabulário científico, imagens de decomposição e reflexão sobre a existência. Publicou em vida o livro Eu, em 1912.", context: "Sua poesia ocupa uma posição singular entre o fim do século XIX e o Modernismo, aproximando temas filosóficos de uma linguagem áspera e pouco convencional." },
    "bernardo-guimaraes": { name: "Bernardo Guimarães", bio: "Bernardo Guimarães foi romancista e poeta mineiro do século XIX, associado ao Romantismo brasileiro. Sua ficção explorou paisagens, costumes e conflitos sociais do interior do país.", context: "Suas obras permitem acompanhar a formação do romance regional e confrontar a idealização romântica com temas concretos como escravidão, poder e vida provincial." },
    "coelho-netto": { name: "Coelho Netto", bio: "Coelho Netto foi escritor, jornalista e político maranhense, autor de romances, contos, crônicas e peças. Teve presença marcante na vida literária brasileira entre o fim do século XIX e o início do XX.", context: "A variedade de gêneros e registros de sua produção mostra a expansão do mercado editorial e da cultura urbana na Primeira República." },
    "goncalves-dias": { name: "Gonçalves Dias", bio: "Gonçalves Dias foi poeta, dramaturgo e pesquisador maranhense do século XIX, figura central da primeira geração romântica brasileira. Sua poesia tornou-se especialmente conhecida pelo indianismo e pela lírica de exílio.", context: "Sua obra participou da construção literária de uma identidade nacional depois da Independência; hoje também pode ser lida criticamente quanto à representação dos povos indígenas." },
    "gregorio-de-matos": { name: "Gregório de Matos", bio: "Gregório de Matos foi poeta da Bahia colonial, conhecido por versos religiosos, amorosos e satíricos. A tradição o apelidou de Boca do Inferno pela crítica mordaz à sociedade de seu tempo.", context: "Sua obra oferece um retrato literário multifacetado da sociedade colonial e é um marco do Barroco em língua portuguesa, embora a transmissão e a atribuição de poemas exijam cuidado editorial." },
    "jose-de-alencar": { name: "José de Alencar", bio: "José de Alencar foi romancista, dramaturgo, jornalista e político cearense, um dos autores centrais do Romantismo brasileiro. Escreveu romances urbanos, históricos, regionalistas e indianistas.", context: "Seus livros ajudaram a imaginar uma literatura nacional independente, e também permitem examinar como o século XIX representou povos indígenas, escravidão, gênero e formação social." },
    "joao-marques-de-carvalho": { name: "João Marques de Carvalho", bio: "João Marques de Carvalho foi escritor, jornalista e diplomata paraense. Sua produção está ligada à vida intelectual da Amazônia e à circulação de ideias literárias entre o Brasil e a Europa.", context: "Ler seus contos amplia o mapa da literatura brasileira para além dos centros editoriais do Sudeste e evidencia a diversidade regional da produção oitocentista." },
    "joao-simoes-lopes-neto": { name: "João Simões Lopes Neto", bio: "João Simões Lopes Neto foi escritor e empresário de Pelotas, no Rio Grande do Sul. É conhecido por narrativas que incorporam a fala, as memórias e os personagens do mundo rural sul-rio-grandense.", context: "Sua escrita regionalista transforma a oralidade em recurso literário e dá centralidade a uma paisagem e a uma experiência histórica próprias do Sul do Brasil." },
    "julia-lopes-de-almeida": { name: "Júlia Lopes de Almeida", bio: "Júlia Lopes de Almeida foi romancista, contista, cronista e dramaturga carioca, uma das escritoras brasileiras mais publicadas de sua época. Sua obra atravessa a vida doméstica, a cidade e as mudanças sociais da virada do século.", context: "Sua presença no acervo ajuda a reconhecer a participação decisiva das mulheres na literatura brasileira e a observar como seus livros discutem educação, casamento, trabalho e autonomia." },
    "lima-barreto": { name: "Lima Barreto", bio: "Lima Barreto foi romancista, cronista e jornalista carioca da Primeira República. Sua ficção acompanha personagens comuns e expõe burocracias, hierarquias raciais e desigualdades da vida urbana.", context: "Com linguagem direta e sátira social, sua obra questiona as promessas de modernização republicana e dá visibilidade a sujeitos frequentemente afastados do centro da narrativa nacional." },
    "machado-de-assis": { name: "Machado de Assis", bio: "Machado de Assis foi escritor, cronista, dramaturgo e crítico carioca, autor de romances e contos que marcaram a literatura brasileira. De origem humilde, acompanhou as transformações do Rio de Janeiro do século XIX e foi um dos fundadores da Academia Brasileira de Letras.", context: "Sua ficção combina ironia, experimentação narrativa e observação das relações de classe, raça, gênero e poder. A voz dos narradores muitas vezes exige que o leitor desconfie do que parece ser contado." },
    "maria-firmina-dos-reis": { name: "Maria Firmina dos Reis", bio: "Maria Firmina dos Reis foi escritora e professora maranhense. Publicou Úrsula em 1859, romance hoje reconhecido como pioneiro na literatura abolicionista brasileira, e também escreveu contos, poemas e textos para a imprensa.", context: "Sua trajetória desloca o cânone ao destacar a autoria de uma mulher negra no século XIX; em Úrsula, personagens escravizados recebem interioridade e voz narrativa em uma crítica à escravidão." },
    "pinto-da-rocha": { name: "Pinto da Rocha", bio: "Pinto da Rocha é o nome pelo qual o catálogo do Project Gutenberg identifica o autor de Talitha: Evangelho em Três Atos. Os registros biográficos disponíveis são escassos, por isso este perfil se limita ao que a edição e os catálogos permitem confirmar.", context: "Manter a obra no acervo com uma biografia cautelosa permite registrar autores menos documentados sem preencher lacunas com informações não verificadas." },
    "raul-pompeia": { name: "Raul Pompeia", bio: "Raul Pompeia foi escritor, jornalista, professor e artista gráfico fluminense. Sua obra mais conhecida, O Ateneu, transforma lembranças de internato em uma narrativa de formação marcada pela experimentação formal.", context: "Sua prosa combina crítica às instituições, memória subjetiva e observação social, aproximando o romance brasileiro de procedimentos associados ao Impressionismo." },
    "visconde-de-taunay": { name: "Visconde de Taunay", bio: "Alfredo d'Escragnolle Taunay, Visconde de Taunay, foi escritor, militar, engenheiro e político brasileiro. A experiência de viagem e da Guerra do Paraguai atravessa parte de sua produção literária.", context: "Seus romances e relatos ajudam a compreender o regionalismo do século XIX e a relação entre observação da paisagem, experiência militar e construção de personagens." },
};

const workProfiles = {
    OL1003017W: ["Memórias póstumas de Brás Cubas", "Brás Cubas narra sua vida depois de morto, interrompendo a história para conversar com o leitor e comentar a própria escrita. Entre amores, ambições e fracassos, suas memórias expõem a elite do Rio de Janeiro oitocentista.", "Publicado em livro em 1881, o romance marca a fase madura de Machado de Assis e desloca convenções do romance brasileiro: em vez de uma narrativa linear e de um narrador que inspira confiança, temos um defunto-autor que interrompe a história, escolhe o que revelar e tenta dirigir a leitura. Essa liberdade formal não é mero jogo. Ao contar a própria vida, Brás deixa escapar a vaidade e as contradições de um homem da elite imperial; o humor expõe como privilégio, escravidão e desigualdade são naturalizados ou apagados em sua versão dos fatos.\n\nLer a obra hoje é perceber que a disputa pela memória continua atual: quem tem o poder de contar a história, justificar vantagens e falar pelos outros? Brás procura conquistar a simpatia do leitor, mas suas omissões e mudanças de tom exigem que desconfiemos dele e construamos nosso próprio julgamento. Vale a leitura porque Machado transforma esse trabalho do leitor em parte do romance: os capítulos breves, as digressões e as provocações fazem da forma uma investigação sobre poder, responsabilidade e autoengano. Assim, a obra permanece central não só por sua inovação narrativa, mas porque ainda nos ensina a ler criticamente as histórias que contamos sobre nós mesmos e sobre o Brasil.", ["Narrador não confiável", "Memória", "Ironia", "Desigualdade social", "Escravidão", "Privilégio"]],
    OL1003040W: ["Dom Casmurro", "Bento Santiago reconstrói sua infância, seu casamento com Capitu e as suspeitas que passaram a dominar sua vida. Tudo chega pela voz do próprio Bento, que tenta convencer o leitor de sua versão.", "Publicado em 1899, Dom Casmurro transforma uma história de amor e ciúme em um dos grandes experimentos brasileiros sobre memória e ponto de vista. Bento escreve depois dos acontecimentos e controla sozinho o relato: Capitu, centro de sua acusação, não dispõe de voz equivalente para responder. A dúvida sobre a traição importa menos como enigma a solucionar do que como teste da autoridade do narrador e dos preconceitos que moldam seu julgamento.\n\nA obra continua atual porque mostra como uma narrativa segura de si pode converter suspeita em aparente evidência — algo especialmente poderoso quando uma das partes controla o que será lembrado. Vale lê-la para acompanhar como Machado distribui pistas, silêncios e ambiguidades e para perceber o quanto nossas conclusões dependem de quem conta a história. O romance permanece aberto ao debate justamente porque exige que o leitor examine também os próprios critérios de confiança.", ["Memória", "Ciúme", "Narrador não confiável", "Ambiguidade", "Gênero e poder"]],
    OL1003079W: ["Quincas Borba", "Rubião herda a fortuna e a filosofia de Quincas Borba e deixa a cidade de Barbacena rumo ao Rio de Janeiro. A proximidade com o casal Sofia e Cristiano Palha acelera sua ruína financeira e mental.", "Publicado entre 1886 e 1891, Quincas Borba prolonga a investigação de Machado sobre as relações entre dinheiro, prestígio e interesse. Rubião herda uma fortuna e uma filosofia — o Humanitismo —, mas não consegue distinguir a retórica grandiosa das conveniências de quem o cerca. A ironia do romance põe em contato a máxima de que “ao vencedor, as batatas” e uma sociedade em que poucos vencem à custa de muitos.\n\nA leitura ainda conversa com um presente marcado por competição e discursos que apresentam desigualdades como resultado natural do mérito. Machado, porém, não oferece uma fórmula simples: faz rir do sistema e sentir a vulnerabilidade de Rubião. Vale a leitura por essa combinação de sátira e compaixão, e por mostrar como ideias aparentemente universais podem servir a interesses particulares.", ["Poder e interesse", "Loucura", "Sátira", "Humanitismo", "Desigualdade"]],
    OL1525650W: ["Iracema", "A jovem tabajara Iracema encontra Martim, colonizador português ligado a um povo rival. O romance acompanha a relação entre os dois e o nascimento de Moacir, em uma narrativa associada à formação simbólica do Ceará.", "Publicado em 1865 e chamado por Alencar de “lenda do Ceará”, Iracema é uma experiência decisiva de prosa poética do Romantismo. A musicalidade, as imagens da natureza e a invenção de uma linguagem literária nacional ajudaram o livro a ocupar lugar central no imaginário brasileiro. Essa construção, porém, conta a origem do país a partir de um encontro colonial idealizado e converte a personagem indígena em símbolo de uma nação que se forma sob liderança europeia.\n\nLer Iracema hoje permite apreciar a força estética do texto e, ao mesmo tempo, perguntar quem ganha voz quando a literatura inventa uma origem nacional. A tensão entre beleza, violência colonial e apagamento não diminui a obra: torna a leitura mais rica e necessária para compreender como o Brasil foi narrado. Vale lê-la tanto por sua linguagem quanto pelo debate crítico que ela continua abrindo.", ["Indianismo", "Colonização", "Identidade nacional", "Linguagem e natureza", "Representação indígena"]],
    OL7058886W: ["O Cortiço", "No Rio de Janeiro, o cortiço de João Romão cresce junto com as ambições do proprietário e a vida de seus moradores. Relações de trabalho, desejo, exploração e convivência se cruzam em torno desse espaço coletivo.", "Publicado em 1890, O Cortiço é um marco do Naturalismo no Brasil e faz do espaço coletivo o motor da narrativa: a moradia, o trabalho e a busca por ascensão aproximam destinos que o romance observa em conjunto. A trajetória de João Romão liga enriquecimento a exploração, enquanto a vida dos moradores expõe as hierarquias e tensões da cidade em transformação. A forma naturalista também carrega teorias deterministas e raciais do século XIX, que hoje precisam ser lidas criticamente, não tomadas como explicações neutras.\n\nO livro permanece relevante porque permite discutir moradia, desigualdade, trabalho e quem tem o poder de prosperar numa sociedade urbana. Vale a leitura por seu ritmo coletivo e pela possibilidade de confrontar a crítica social do romance com os limites ideológicos de seu tempo. O leitor encontra, assim, tanto um retrato literário vigoroso quanto material para questionar como se constroem as ideias de ambiente, raça e destino.", ["Vida urbana", "Trabalho e exploração", "Desigualdade", "Naturalismo", "Determinismo"]],
    OL1003152W: ["Helena", "Após a morte do conselheiro Vale, Helena é acolhida pela família que ele reconheceu em testamento. Sua chegada altera as relações entre Estácio, D. Úrsula e os demais personagens, enquanto segredos do passado vêm à tona.", "Publicado em 1876, Helena pertence à fase romântica de Machado, mas já revela seu interesse pelas regras sociais que condicionam a vida privada. A entrada da protagonista numa família abastada depende de um testamento e de uma origem cuidadosamente administrada; afeto e pertencimento aparecem ligados a dinheiro, reputação e posição de classe. O romance acompanha uma mulher cuja margem de escolha é estreita, mesmo quando todos falam de seus sentimentos.\n\nA obra importa por mostrar Machado trabalhando dentro das convenções do romance sentimental e, ao mesmo tempo, observando as pressões que essas convenções escondem. Lê-la hoje ajuda a perceber como família, herança e respeitabilidade ainda podem definir quem é aceito e quem precisa provar que merece pertencer. Vale também como contraponto aos romances maduros do autor: permite acompanhar a formação de seu olhar psicológico e social.", ["Afeto e convenção", "Herança", "Classe social", "Vida das mulheres"]],
    OL1003044W: ["Esaú e Jacó", "Os gêmeos Pedro e Paulo divergem desde a juventude e levam a rivalidade para a vida adulta, inclusive na política. Flora, dividida entre os irmãos, torna-se o centro afetivo de uma disputa que atravessa a passagem do Império à República.", "Publicado em 1904, Esaú e Jacó observa a passagem do Império à República sem transformar a mudança de regime numa renovação automática da sociedade. A rivalidade dos gêmeos Pedro e Paulo dá forma doméstica a disputas políticas, enquanto Flora enfrenta a pressão de ser escolhida entre projetos que os homens apresentam como inconciliáveis. O conselheiro Aires narra com distância e hesitação, deixando claro que interpretar os acontecimentos também é uma forma de poder.\n\nO romance permanece atual porque pergunta o que muda de fato quando mudam os nomes e os símbolos do poder. Vale a leitura para acompanhar como Machado aproxima política e vida cotidiana e para perceber a ironia de uma história em que a disputa parece intensa, mas as estruturas sociais sobrevivem à troca de regime.", ["Império e República", "Política", "Narrador", "Gênero e poder"]],
    OL1525648W: ["Ubirajara", "O romance acompanha Jaguarê, guerreiro araguaia que busca afirmar seu valor e passa por alianças, provas e mudanças de identidade até se tornar Ubirajara.", "Publicado em 1874, Ubirajara integra o projeto indianista de José de Alencar, que procurava imaginar uma literatura nacional anterior à presença portuguesa. O romance dá centralidade a personagens indígenas e constrói um universo de coragem, parentesco e alianças; essa representação, contudo, é uma criação literária de um autor do século XIX, não um registro etnográfico nem substituto das vozes indígenas.\n\nA obra merece leitura tanto por sua participação na invenção romântica do Brasil quanto pela possibilidade de examinar criticamente essa invenção. Hoje, perguntar como identidades indígenas foram narradas por escritores não indígenas ajuda a distinguir imaginação nacional de diversidade histórica real. A linguagem e o enredo de aventura tornam esse debate acessível sem apagar seus limites.", ["Indianismo", "Identidade nacional", "Representação indígena", "Romantismo"]],
    OL2595426W: ["O Ateneu", "Sérgio relembra os anos vividos no internato Ateneu, instituição dirigida por Aristarco. A escola concentra amizades, rivalidades, hierarquias e experiências de formação sob o olhar retrospectivo do narrador.", "Publicado em 1888, O Ateneu transforma o internato numa miniatura de instituições que prometem formar os jovens enquanto reproduzem competição, autoridade e desigualdade. Sérgio conta a experiência depois de vivê-la, e sua memória mistura fascínio, ressentimento e observação; a escola surge menos como espaço neutro de educação do que como teatro de relações de poder. A prosa intensa de Raul Pompeia rompe com a descrição transparente e aproxima o leitor da percepção subjetiva do narrador.\n\nO livro continua pertinente para quem pensa sobre educação, disciplina e formação social: que valores uma instituição transmite na prática, para além do que declara ensinar? Vale lê-lo pela força das imagens e pela maneira como a memória adulta reorganiza a experiência da infância, convidando o leitor a desconfiar tanto da instituição quanto de quem a recorda.", ["Educação", "Memória", "Autoridade", "Desigualdade", "Formação"]],
    OL15371728W: ["A Falência", "No Rio de Janeiro do fim do século XIX, a crise financeira do negociante Francisco Teodoro atinge a família e as pessoas ao seu redor. A narrativa acompanha especialmente as consequências da ruína para as mulheres da casa.", "Publicado em 1901, A Falência coloca a crise de um negócio no centro da vida familiar e mostra que a prosperidade depende de relações frágeis de trabalho, confiança e reputação. Júlia Lopes de Almeida desloca o olhar para as consequências da ruína sobre as mulheres, cuja segurança material está ligada a decisões e rendas que não controlam plenamente. Dinheiro, casamento e autonomia deixam de ser assuntos separados.\n\nA obra tem importância também por ampliar a presença de uma escritora na história do romance brasileiro e por tratar a casa como espaço econômico e social, não apenas íntimo. Lê-la hoje ilumina debates sobre dependência financeira, trabalho invisível e possibilidades de escolha. Vale a leitura pelo modo como a crise expõe estruturas que pareciam estáveis e altera a vida de cada personagem de maneira desigual.", ["Dinheiro", "Família", "Autonomia feminina", "Trabalho", "Classe social"]],
    OL2306387W: ["Triste Fim de Policarpo Quaresma", "Policarpo Quaresma tenta servir ao Brasil por meio do estudo da cultura nacional, de reformas agrícolas e de sua participação política. Seus projetos esbarram na burocracia, no preconceito e na violência do governo de Floriano Peixoto.", "Publicado em 1911, o romance de Lima Barreto acompanha um patriota que leva a sério demais as promessas da República e os discursos sobre uma identidade nacional. A sequência de seus projetos — culturais, econômicos e políticos — revela instituições pouco dispostas a acolher quem tenta mudá-las. A sátira não ridiculariza apenas Quaresma: expõe a distância entre o ideal de país e a violência de um Estado que exige obediência.\n\nA leitura segue atual porque patriotismo, identidade nacional e reformas continuam sendo disputados, e porque o livro pergunta quem pode definir o que é “ser brasileiro”. Vale lê-lo pelo equilíbrio entre humor e tragédia e pela perspectiva crítica de Lima Barreto sobre burocracia, autoritarismo e exclusão na Primeira República.", ["Nacionalismo", "República", "Burocracia", "Autoritarismo", "Identidade nacional"]],
    OL4561054W: ["Inocência", "No sertão de Mato Grosso, Cirino, que se apresenta como médico, conhece Inocência, jovem prometida por seu pai a outro homem. O encontro abre um conflito entre desejo, autoridade familiar e códigos de honra.", "Publicado em 1872, Inocência ajudou a consolidar o romance regionalista ao levar o sertão de Mato Grosso ao centro da ficção, com atenção à paisagem, aos costumes e aos deslocamentos. A história de amor, porém, é condicionada pelo poder patriarcal: a vontade da jovem é subordinada à autoridade familiar e a códigos de honra que decidem seu futuro. A experiência de Visconde de Taunay como viajante contribui para a observação do ambiente, sem tornar o romance um documento neutro.\n\nLer o livro hoje permite reconhecer a importância de representar regiões afastadas dos centros urbanos e, simultaneamente, questionar a liberdade negada às mulheres na trama. Vale pela combinação entre narrativa de viagem, drama e descrição regional, e pelo debate sobre como a literatura transforma costumes em destino.", ["Regionalismo", "Patriarcado", "Liberdade", "Paisagem", "Costumes"]],
    OL3422516W: ["A Escrava Isaura", "Isaura, escravizada e criada com educação refinada, tenta escapar do domínio de Leôncio e da violência que ele exerce. A narrativa acompanha sua busca por proteção e liberdade em uma sociedade escravista.", "Publicado em 1875, A Escrava Isaura alcançou ampla circulação e participou da popularização de argumentos abolicionistas por meio de uma narrativa folhetinesca. A condição da protagonista evidencia a violência da escravidão, mas a maneira como o romance a apresenta — branca, educada e virtuosa segundo os padrões de respeitabilidade da época — também revela os limites raciais de parte do imaginário abolicionista. Essa contradição é indispensável para compreender o livro em seu contexto.\n\nA obra permanece relevante porque permite discutir como histórias de denúncia escolhem quais vítimas serão consideradas dignas de compaixão e quais experiências deixam à margem. Vale lê-la tanto pelo impacto histórico e pela força melodramática quanto para analisar criticamente a representação da escravidão, sem confundir a intenção abolicionista do romance com uma representação completa da experiência negra.", ["Escravidão", "Abolicionismo", "Representação racial", "Gênero", "Folhetim"]],
    PG2837: ["Lendas do Sul", "João Simões Lopes Neto reúne narrativas ligadas às tradições, personagens e paisagens do Rio Grande do Sul. A voz de Blau Nunes dá às histórias um ritmo oral e uma perspectiva regional.", "Publicado em 1913, Lendas do Sul converte histórias transmitidas e imaginadas como tradição gaúcha em literatura escrita, preservando marcas da oralidade na voz de Blau Nunes. O livro participa da formação do regionalismo brasileiro e desloca o foco para personagens, paisagens e modos de falar do extremo sul. Ao mesmo tempo, toda tradição recolhida é também uma escolha: a obra constrói uma imagem de pertencimento e identidade, em vez de simplesmente reproduzir uma cultura sem mediação.\n\nLer os contos hoje permite perceber como a oralidade pode estruturar uma narrativa e como regiões diferentes produzem seus próprios repertórios literários. Vale pela força da voz narrativa, pelo imaginário local e pela oportunidade de discutir quem registra as tradições e como elas se transformam ao entrar no livro.", ["Oralidade", "Regionalismo", "Memória", "Identidade cultural"]],
    PG28691: ["Contos do Norte", "A coletânea apresenta narrativas associadas à região amazônica e ao Norte do Brasil, observadas por João Marques de Carvalho em diferentes ambientes e situações sociais.", "Contos do Norte reúne narrativas de João Marques de Carvalho e registra uma produção literária paraense do fim do século XIX, período em que a vida intelectual de Belém se relacionava às mudanças econômicas e culturais da Amazônia. Seu valor para o acervo está também em ampliar o mapa de uma literatura brasileira muitas vezes contada a partir do Sudeste.\n\nA leitura permite observar como um escritor de sua época transforma espaços e relações regionais em matéria ficcional. Como há menos estudos e informações de circulação ampla sobre este título, é melhor tratá-lo como oportunidade de descoberta e pesquisa do que atribuir-lhe, sem evidência, um papel canônico. Vale justamente pelo contato com uma voz e um contexto pouco presentes nas seleções mais conhecidas.", ["Literatura amazônica", "Regionalismo", "Belém", "Século XIX"]],
    PG29040: ["Como e Por Que Sou Romancista", "Neste texto autobiográfico, José de Alencar relembra sua formação, suas leituras e o caminho que o levou à escrita de romances. O autor também comenta escolhas de linguagem e o projeto de uma literatura brasileira.", "Escrito em 1873 e publicado postumamente, Como e Por Que Sou Romancista é um testemunho em que José de Alencar explica sua formação, sua prática de escritor e suas ideias sobre a língua e o romance no Brasil. Em vez de depender apenas de interpretações posteriores, o leitor encontra o próprio autor construindo a imagem de sua trajetória e defendendo um projeto literário nacional.\n\nO texto importa porque ajuda a entender como o Romantismo brasileiro pensou a relação entre literatura, linguagem e identidade. Lê-lo hoje também ensina a tratar documentos autobiográficos criticamente: são fontes valiosas, mas narram uma vida a partir de escolhas e justificativas. Vale como chave de leitura para os romances de Alencar e como registro de um escritor refletindo sobre seu ofício.", ["Autobiografia", "Romantismo", "Língua portuguesa", "Literatura nacional"]],
    PG29161: ["Entre as Nymphéas", "A narrativa acompanha personagens e relações sociais em um ambiente marcado por convenções, afetos e observação da vida cotidiana, traços da ficção de João Marques de Carvalho.", "Entre as Nymphéas, de João Marques de Carvalho, integra a produção de um escritor paraense ligado à imprensa e à vida literária de Belém no fim do século XIX. A presença do título entre as obras de leitura integral dá acesso a um repertório regional pouco conhecido fora de estudos especializados e ajuda a descentralizar a história do romance brasileiro.\n\nComo as informações críticas disponíveis sobre esta obra são limitadas, seu interesse está em poder ser lida diretamente, sem antecipar conclusões que as fontes não sustentam. O leitor pode observar as convenções narrativas e sociais do período e comparar essa experiência com títulos mais consagrados. Recuperar livros assim amplia o acervo e abre caminho para novas pesquisas, em vez de repetir somente o cânone já estabelecido.", ["Literatura paraense", "Imprensa", "Vida cotidiana", "Século XIX"]],
    PG30341: ["Contos Paraenses", "A coletânea reúne contos de João Marques de Carvalho ligados a Belém e ao Pará, com personagens e situações que refletem a sociedade amazônica de seu tempo.", "Contos Paraenses reúne ficção ligada a Belém e ao Pará por João Marques de Carvalho e permite aproximar a leitura da vida social amazônica no fim do século XIX. A coletânea importa para uma história literária que não reduza o país a seus centros editoriais mais conhecidos: ela registra temas, ambientes e perspectivas de uma região em transformação.\n\nLer esses contos hoje é também perguntar como a Amazônia foi representada por escritores de seu próprio circuito cultural e quais aspectos da experiência local ganham espaço na ficção. Como a recepção crítica do volume é menos documentada, o perfil evita proclamar uma influência que não está comprovada. Vale a leitura como descoberta de um repertório regional e como ponto de partida para comparar outras narrativas brasileiras do período.", ["Literatura amazônica", "Belém", "Conto", "Representação regional"]],
    PG33056: ["Histórias sem Data", "Machado de Assis reúne contos de diferentes momentos e ambientes, nos quais pequenas decisões, convenções sociais e desejos escondidos alteram o curso da vida dos personagens.", "Publicado em 1884, Histórias sem Data reúne contos em que Machado de Assis explora a distância entre as aparências sociais e os desejos, interesses ou autoenganos que as sustentam. A forma breve concentra conflitos em gestos e decisões aparentemente comuns, enquanto a ironia impede que a narrativa se transforme numa explicação moral simples. O título sugere histórias que não dependem de uma época específica, embora cada uma dialogue com as convenções de seu tempo.\n\nA coletânea é uma boa entrada para perceber como Machado constrói personagens e narradores em poucas páginas. Seus temas — reputação, casamento, ambição e poder — seguem reconhecíveis, mas o prazer está também em acompanhar como a linguagem altera nosso julgamento. Vale a leitura para conhecer o contista e para experimentar uma literatura que confia na inteligência ativa do leitor.", ["Conto", "Ironia", "Aparências", "Relações sociais"]],
    PG33611: ["Cenas de Viagem", "Visconde de Taunay registra paisagens, deslocamentos e encontros observados em viagens pelo interior do Brasil. O olhar combina descrição do território com impressões de quem percorre regiões em transformação.", "Cenas de Viagem aproxima escrita literária, observação e deslocamento pelo interior brasileiro. O olhar de Visconde de Taunay transforma paisagens e encontros em relato, permitindo ver como viajantes do século XIX descreviam territórios e convertiam a experiência em conhecimento. Esses textos também revelam que observar nunca é um ato neutro: a seleção do que merece descrição expressa a posição e os interesses de quem viaja.\n\nA obra vale hoje como documento de sensibilidades e modos de representar o país, além de narrativa de viagem. Lê-la junto de romances regionalistas de Taunay ajuda a comparar o registro do deslocamento com a elaboração ficcional. Como em qualquer relato histórico, convém distinguir a experiência narrada da realidade diversa das pessoas e comunidades observadas.", ["Viagem", "Paisagem", "Território", "Olhar do viajante"]],
    PG34750: ["Mistério do Natal", "Coelho Netto constrói uma narrativa em torno do Natal, articulando mistério, expectativa e relações humanas em uma história de tom literário e moral.", "Mistério do Natal é um título de Coelho Netto, escritor de enorme presença editorial entre o fim do século XIX e o começo do XX, hoje menos lido do que alguns de seus contemporâneos. A narrativa se organiza em torno de uma ocasião reconhecível e mobiliza expectativas afetivas e morais típicas da literatura de circulação ampla. Seu interesse também está em documentar quais histórias e valores chegavam aos leitores daquele período.\n\nNão é preciso apresentar o livro como uma obra decisiva do cânone para justificar sua leitura. Ele oferece a chance de conhecer outra faceta de um autor prolífico e de comparar a literatura popular e sentimental da época com formas mais experimentais. Vale como janela histórica e como convite a redescobrir títulos que a memória literária deixou em segundo plano.", ["Natal", "Literatura de circulação", "Costumes", "Século XX"]],
    PG44540: ["Cinco Minutos", "Um encontro casual em um ônibus aproxima o narrador de Carlota. A história acompanha a paixão, a distância e as coincidências que conduzem o casal ao longo de anos.", "Publicado em 1856, Cinco Minutos é um dos primeiros romances de José de Alencar e mostra a ficção sentimental acompanhando uma cidade em modernização. O encontro casual, a paixão e as coincidências são organizados numa narrativa breve, originalmente ligada à circulação em folhetins; o formato aproxima a literatura do cotidiano e de um público leitor em expansão.\n\nO livro importa menos como retrato transparente do Rio do que como experiência de imaginação urbana e de leitura seriada no Brasil imperial. Hoje, vale pela rapidez narrativa e por permitir observar como o romance constrói o amor por meio de expectativas, obstáculos e idealizações. É uma porta de entrada acessível para o início da carreira de Alencar e para as convenções românticas que ele ajudou a popularizar.", ["Romantismo", "Folhetim", "Vida urbana", "Amor idealizado"]],
    PG53101: ["A Mão e a Luva", "Guiomar, jovem de origem modesta, precisa decidir entre pretendentes e expectativas de ascensão social. Sua escolha é guiada tanto pelo afeto quanto por uma avaliação lúcida de caráter e futuro.", "Publicado em 1874, A Mão e a Luva acompanha Guiomar numa sociedade em que casamento também define segurança e posição social. A protagonista não é apenas conduzida pelos pretendentes: pondera interesses, afetos e possibilidades, e essa capacidade torna visíveis as restrições que cercam sua escolha. O romance pertence à fase inicial de Machado, mas já demonstra sua atenção a motivações ambíguas e às negociações discretas da vida familiar.\n\nA obra merece ser lida ao lado dos romances posteriores do autor para acompanhar a transformação de sua técnica e de sua visão social. Continua atual por mostrar que decisões íntimas são tomadas dentro de condições materiais e expectativas de gênero. Vale pela personagem de Guiomar e por permitir discutir agência sem ignorar os limites impostos a ela.", ["Casamento", "Classe social", "Autonomia feminina", "Romance urbano"]],
    PG55797: ["Memorial de Ayres", "Em forma de diário, o conselheiro Aires registra encontros, impressões e a história de Fidélia e Tristão. O narrador observa mais do que intervém e deixa lacunas em seus comentários.", "Publicado em 1908, Memorial de Ayres é o último romance de Machado e adota a forma de diário de um narrador idoso, diplomático e atento às convenções. As anotações de Aires registram encontros e a história de Fidélia e Tristão, mas sua discrição deixa zonas de dúvida: o que ele observa, o que prefere não dizer e o que talvez não compreenda? A escrita cotidiana se torna forma de refletir sobre idade, luto, afeto e memória.\n\nO livro importa por mostrar que a experimentação machadiana não depende apenas de grandes rupturas: também pode nascer de uma voz contida e de lacunas. Lê-lo hoje convida a pensar como narramos a vida alheia e como a polidez pode suavizar conflitos. Vale pela serenidade ambígua do diário e como despedida literária de um autor que ainda confia ao leitor o trabalho de interpretar.", ["Diário", "Memória", "Velhice", "Luto", "Narrador"]],
    PG57001: ["Papéis Avulsos", "A coletânea reúne contos de Machado de Assis sobre ambição, loucura, ciência, política e relações sociais. Cada narrativa experimenta uma situação e uma voz próprias.", "Publicado em 1882, Papéis Avulsos reúne contos que se tornaram centrais na obra de Machado, entre eles “O alienista”. A coletânea põe em cena a autoridade da ciência, a ambição política, a vaidade e as convenções sociais, mas cada história encontra uma forma própria de testar essas ideias. Em vez de oferecer respostas estáveis, Machado faz a ironia deslocar o ponto de vista e expor os limites de quem pretende classificar os outros.\n\nLer o volume hoje é reconhecer como instituições e discursos técnicos podem ganhar poder sobre a vida cotidiana — questão que continua relevante. Vale pela variedade de vozes e situações e por mostrar o conto como espaço de experimentação, capaz de condensar um problema social sem encerrá-lo numa moral previsível. “O alienista” é uma entrada conhecida, mas o conjunto revela ainda mais da amplitude do escritor.", ["Conto", "Ciência e poder", "Sátira", "Instituições", "Ironia"]],
    PG61653: ["Poesias Completas", "O volume reúne a produção poética de Machado de Assis em diferentes fases, da sensibilidade romântica a formas mais reflexivas e contidas.", "As Poesias Completas permitem acompanhar um Machado menos lembrado que o romancista e o contista. Ao reunir diferentes fases, o volume mostra mudanças de tom e forma e o diálogo do autor com tradições poéticas de sua época. A leitura do conjunto evita reduzir uma carreira extensa a uma única imagem — a do ironista dos grandes romances — e evidencia a diversidade de gêneros em que atuou.\n\nO interesse atual está em observar como um escritor transforma e revisita convenções ao longo do tempo. Vale ler os poemas sem esperar que reproduzam a prosa madura: justamente as diferenças ajudam a entender sua formação, suas escolhas e o campo literário do século XIX. O volume também convida a investigar quais poemas ganharam circulação e como a edição organiza uma produção dispersa.", ["Poesia", "Forma", "Tradição literária", "Trajetória autoral"]],
    PG62525: ["Histórias Brasileiras", "Visconde de Taunay apresenta narrativas ambientadas no Brasil e voltadas a personagens, costumes e conflitos ligados à experiência nacional do século XIX.", "Histórias Brasileiras reúne narrativas de Visconde de Taunay e permite observar como a ficção do século XIX transformava paisagens, costumes e conflitos em imagens de experiência nacional. A variedade de situações oferece contraponto à leitura isolada de seus romances mais conhecidos e ajuda a perceber o trânsito entre regionalismo, observação social e formas breves.\n\nA coletânea importa como registro da diversidade de gêneros e de representações do território no período. Lê-la hoje pede atenção ao olhar de época: quais grupos aparecem como protagonistas, quais são descritos de fora e que valores organizam a narrativa? Vale pelo panorama oferecido e pela possibilidade de comparar as histórias com outras vozes brasileiras do mesmo século.", ["Conto", "Território", "Costumes", "Século XIX"]],
    PG62896: ["Ao Entardecer: Contos Vários", "Taunay reúne contos de temas e ambientes diversos, com atenção a encontros, lembranças e mudanças de humor que surgem na vida comum.", "Ao Entardecer: Contos Vários apresenta Visconde de Taunay trabalhando com narrativas breves e situações diversas. O conto permite concentrar a atenção num encontro, numa lembrança ou numa mudança de perspectiva sem a extensão do romance; a coletânea ajuda a conhecer essa dimensão de um autor também associado à ficção regionalista.\n\nO livro é relevante como parte da cultura impressa que ampliou a circulação de narrativas curtas no Brasil oitocentista. Vale para experimentar diferentes temas e observar como cada história organiza seu efeito. Como há menos recepção crítica acessível sobre o volume como conjunto, sua leitura também pode ser exploratória, sem atribuir-lhe uma influência que as fontes não comprovam.", ["Conto", "Memória", "Vida cotidiana", "Imprensa"]],
    PG63606: ["Lupe", "A narrativa acompanha Lupe e as relações afetivas e sociais que definem suas escolhas. Affonso Celso combina observação de costumes com os valores morais e sentimentais de seu tempo.", "Lupe permite conhecer a ficção de Affonso Celso para além de sua atuação política e de seus textos patrióticos mais conhecidos. A narrativa de costumes registra modelos de comportamento, afetos e expectativas sociais da virada do século XIX para o XX, oferecendo uma perspectiva sobre a produção literária de um período de expansão editorial.\n\nSeu interesse hoje está também em ler historicamente aquilo que pode parecer familiar ou datado: que valores o livro apresenta como desejáveis, e que escolhas oferece às personagens? Como a obra é menos estudada e sua fortuna crítica é limitada, é mais responsável apresentá-la como descoberta do acervo do que como marco canônico. Vale para ampliar repertório e comparar convenções de personagem com autores mais conhecidos.", ["Costumes", "Afeto", "Valores sociais", "Virada do século"]],
    PG67594: ["A Intrusa", "A chegada de uma nova mulher à casa de Argemiro altera a rotina da família e revela tensões em torno de luto, cuidado, confiança e autoridade doméstica.", "Publicado em 1908, A Intrusa faz da casa um espaço de relações sociais, trabalho de cuidado e disputa por confiança. A chegada de uma nova mulher altera a rotina de Argemiro e de sua filha, e Júlia Lopes de Almeida observa como luto, autoridade e dependência se reorganizam no cotidiano doméstico. O lar deixa de ser apenas cenário privado e aparece ligado às condições materiais e ao trabalho, em especial ao trabalho feminino.\n\nA obra tem importância por integrar a produção de uma escritora central da literatura brasileira, cuja presença foi por muito tempo diminuída em histórias literárias. Lê-la hoje abre conversa sobre cuidado, reputação e autonomia dentro da família. Vale pela perspectiva social e por deslocar para o centro da narrativa experiências que muitas vezes ficam invisíveis quando a casa é tratada como espaço sem política.", ["Autoria feminina", "Trabalho de cuidado", "Família", "Autonomia"]],
    PG67724: ["O Guarani — Volume I", "No primeiro volume, Peri, indígena ligado à família de D. Antônio de Mariz, aproxima-se de Cecília e enfrenta ameaças que cercam a casa colonial. A aventura apresenta os personagens e o conflito central.", "Publicado originalmente em folhetim em 1857, O Guarani foi um dos romances que deram grande alcance ao projeto indianista de José de Alencar. A aventura de Peri e Cecília combina ação, paisagem e idealização de uma origem nacional; sua primeira parte estabelece o universo colonial e os conflitos que impulsionam a narrativa. A linguagem e o ritmo seriado ajudaram a aproximar o romance de um público amplo.\n\nLê-lo hoje permite compreender como a ficção romântica imaginou o Brasil e como a figura indígena foi convertida em símbolo nacional por um autor não indígena. Vale pela energia narrativa e por abrir uma leitura crítica sobre colonização, representação e memória. Este volume corresponde à primeira parte da edição digital consultada; o desfecho está no segundo volume.", ["Indianismo", "Folhetim", "Colonização", "Identidade nacional"]],
    PG67725: ["O Guarani — Volume II", "O segundo volume conduz a aventura de Peri e Cecília ao desfecho, entre ataques, fugas e decisões que transformam o destino dos personagens e da família de Mariz.", "A segunda parte de O Guarani conclui a aventura iniciada no primeiro volume e mostra como Alencar combina suspense, heroísmo e paisagem para construir uma narrativa de origem nacional. O encerramento tornou-se parte duradoura do imaginário popular, mas a imagem idealizada de indígenas e colonizadores também merece ser examinada à luz de quem criou essa representação e de quais histórias ela deixa de fora.\n\nLer o desfecho junto da primeira parte permite perceber como o folhetim organiza expectativa e recompensa a continuidade. A obra importa tanto por sua influência cultural quanto pelo debate crítico que suscita hoje sobre identidade, colonialismo e representação indígena. Esta página segue a divisão em dois volumes da edição digital disponível no acervo.", ["Indianismo", "Aventura", "Colonização", "Folhetim"]],
    PG67780: ["Yayá Garcia", "Yayá, filha de um negociante de origem humilde, cresce sob a proteção de uma família abastada e se envolve em uma rede de afeto, segredo e diferença de classe.", "Publicado em 1878, Iaiá Garcia pertence à fase inicial de Machado de Assis e acompanha relações afetivas atravessadas por dependência econômica, reputação e diferença de classe. A protagonista cresce sob a proteção de uma família abastada e precisa interpretar intenções alheias ao mesmo tempo que constrói seu próprio caminho. O romance sentimental já revela o interesse de Machado pela psicologia e pelos cálculos que convivem com o afeto.\n\nA obra importa como etapa para compreender a evolução do escritor e como narrativa em que as mulheres agem dentro de limites sociais concretos. Lê-la hoje permite perguntar quanto da autonomia de uma personagem depende dos recursos e da posição que tem à disposição. Vale pela observação cuidadosa das relações familiares e pelo contraste com os romances mais experimentais que viriam depois.", ["Classe social", "Afeto", "Autonomia feminina", "Formação de Machado"]],
    PG67831: ["A Pata da Gazela", "Horácio se apaixona por uma mulher que não conhece bem e passa a idealizá-la a partir de um objeto perdido. A confusão entre aparência, desejo e identidade conduz a trama amorosa.", "Publicado em 1870, A Pata da Gazela usa a comédia urbana para brincar com a idealização romântica e com a distância entre aparência e conhecimento real. Horácio projeta desejos sobre uma mulher que mal conhece, e um objeto perdido alimenta a confusão que move a trama. Alencar transforma os códigos amorosos e a vida social do Rio imperial em matéria leve, mas também observável criticamente.\n\nO romance vale hoje por mostrar como as pessoas constroem imagens umas das outras a partir de sinais incompletos — mecanismo que continua familiar. É também uma entrada agradável na ficção urbana do autor, diferente de seus romances indianistas e regionalistas. A leitura permite discutir humor, gênero e expectativas de comportamento sem exigir que a obra seja tomada como retrato fiel da sociedade.", ["Comédia", "Aparência", "Romantismo", "Vida urbana"]],
    PG67935: ["Relíquias de Casa Velha", "A coletânea póstuma reúne contos, peças e outros textos de Machado de Assis, oferecendo um percurso por diferentes gêneros e momentos de sua produção.", "Publicado postumamente em 1906, Relíquias de Casa Velha reúne textos de gêneros e momentos distintos, entre eles o conto “Pai contra Mãe”. O volume permite encontrar Machado além dos romances mais lidos e observar como sua obra circulou e foi organizada depois de sua morte. A reunião editorial aproxima peças que não nasceram necessariamente como um conjunto, por isso também informa sobre a memória pública do escritor.\n\nA coletânea vale para ampliar o repertório e perceber a variedade da escrita machadiana, inclusive quando aborda escravidão, relações familiares e convenções sociais. Lê-la hoje é uma oportunidade de comparar formas e temas e de perguntar como edições póstumas constroem a imagem de um autor. O texto “Pai contra Mãe”, em particular, oferece uma das representações mais contundentes da violência escravista na prosa brasileira.", ["Conto", "Escravidão", "Memória editorial", "Obra póstuma"]],
    PG69239: ["Era uma vez…", "Júlia Lopes de Almeida reúne histórias que exploram a imaginação, os afetos e as convenções sociais em diferentes situações e registros narrativos.", "Era uma vez… reúne narrativas de Júlia Lopes de Almeida e permite conhecer uma face menos lembrada de uma autora que atuou em vários gêneros e teve ampla circulação em sua época. As histórias articulam imaginação, afetos e convenções sociais, e sua leitura ajuda a recuperar a presença das escritoras na cultura impressa brasileira.\n\nO livro importa também porque amplia o que se costuma chamar de literatura brasileira: não apenas os poucos títulos que se tornaram canônicos, mas obras que circularam e participaram da formação de leitoras e leitores. Vale pela descoberta e pela possibilidade de observar como uma autora negocia os valores de seu tempo. Como a recepção crítica específica do volume é limitada, o perfil não lhe atribui uma influência histórica desmedida.", ["Autoria feminina", "Contos", "Imprensa", "Costumes"]],
    PG70121: ["A Capital Federal", "Coelho Netto observa a capital republicana por meio de personagens, encontros e cenas da vida urbana. A cidade aparece como espaço de mudança, ambição e contraste social.", "A Capital Federal, de Coelho Netto, toma o Rio de Janeiro republicano como cenário de encontros, ambições e contrastes. O título registra a centralidade da cidade na vida política e cultural e oferece material para observar como a literatura acompanhou a urbanização e as mudanças de comportamento na virada do século. A obra se insere na produção volumosa de um escritor que teve grande visibilidade editorial, embora hoje seja menos lido.\n\nLê-la permite reencontrar uma cidade histórica e perguntar quem podia usufruir de suas oportunidades e quem permanecia à margem. Vale como documento literário de uma modernização desigual e como descoberta de um autor importante para a cultura impressa de seu tempo. O perfil evita tratar a obra como marco consensual sem evidência crítica específica.", ["Rio de Janeiro", "Modernização", "Desigualdade urbana", "República"]],
    PG71724: ["Obras Poéticas de Gregório de Matos — Tomo I", "O primeiro tomo reúne poemas atribuídos a Gregório de Matos em registros religiosos, amorosos e satíricos, com a variedade de linguagem característica do Barroco.", "Este tomo reúne poemas atribuídos a Gregório de Matos, figura associada ao Barroco na América portuguesa e lembrada pela variedade de registros: sátira, religiosidade e poesia amorosa. Seus versos oferecem uma linguagem aguda para observar hierarquias, disputas e valores da sociedade colonial, embora tenham circulado por transmissão manuscrita e a atribuição de parte do corpus permaneça objeto de debate editorial.\n\nA leitura importa pela força verbal e porque aproxima o leitor de uma cultura colonial em que a poesia podia comentar publicamente pessoas e poderes. Hoje, vale também aprender a ler com atenção à história dos textos: quem os registrou, atribuiu e reuniu? Reconhecer a incerteza de autoria não apaga a obra; torna mais completa a compreensão de como ela chegou até nós.", ["Barroco", "Sátira", "Sociedade colonial", "Autoria e transmissão"]],
    PG74854: ["Cantos", "Gonçalves Dias reúne poemas líricos e indianistas em que aparecem o exílio, a natureza, a memória e a construção de uma identidade brasileira.", "Publicado em 1846, Cantos é o primeiro livro de Gonçalves Dias e reúne poemas que ajudaram a definir a poesia romântica brasileira. A lírica do exílio e da natureza se articula ao indianismo, movimento que buscava criar símbolos nacionais depois da Independência. Essa contribuição histórica convive com uma questão que permanece necessária: a representação de povos indígenas foi construída por um poeta não indígena e segundo um projeto nacional de seu tempo.\n\nLer a coletânea hoje permite reconhecer sua influência estética e, ao mesmo tempo, discutir os limites dessa imagem de Brasil. Vale pela musicalidade e pelo lugar que ocupa na formação do Romantismo, além de oferecer a oportunidade de ler criticamente poemas que se tornaram parte da memória cultural do país.", ["Romantismo", "Exílio", "Indianismo", "Identidade nacional"]],
    PG28639: ["Talitha: Evangelho em Três Atos", "A obra organiza sua narrativa em três atos e mobiliza personagens e situações de caráter alegórico e moral, conforme a proposta indicada pelo próprio título.", "Talitha: Evangelho em Três Atos é uma peça pouco documentada no panorama literário brasileiro e os dados disponíveis sobre seu autor, Pinto da Rocha, são escassos. O título e a forma dramática permitem situá-la como parte de uma produção teatral que merece ser consultada, mas não autorizam afirmar uma influência ampla ou uma leitura crítica consolidada.\n\nSeu valor para o acervo está em abrir acesso a uma obra rara e permitir que leitores encontrem diretamente suas escolhas de linguagem, estrutura e tema. Vale como descoberta e como lembrete de que a história literária também é composta por textos fora do cânone mais conhecido. Uma leitura mais aprofundada poderá ampliar o perfil quando houver estudos ou documentação confiável adicionais.", ["Teatro", "Alegoria", "Acervo raro", "História literária"]],
    WS1001: ["Eu", "Publicado em 1912, o livro reúne 56 poemas de Augusto dos Anjos, entre eles “Versos Íntimos” e “Monólogo de uma Sombra”. A voz poética aproxima corpo, matéria, ciência e angústia existencial.", "Publicado em 1912, Eu foi o único livro de poemas que Augusto dos Anjos publicou em vida e tornou-se uma das obras mais singulares da poesia brasileira. Seu vocabulário científico, as imagens de decomposição e a musicalidade áspera aproximam corpo e matéria de questões sobre morte e existência. Essa mistura desafia classificações rígidas: há elementos ligados ao Parnasianismo e ao Simbolismo, mas a voz e a dicção do livro não cabem confortavelmente em uma só escola.\n\nA obra continua a provocar leitores por tratar da fragilidade humana sem recorrer a uma linguagem idealizada. Vale lê-la inteira — não apenas por poemas célebres como “Versos Íntimos” — para perceber como ritmo, som e imagens constroem uma visão de mundo. Sua estranheza continua produtiva e mostra que a modernidade poética brasileira se formou por caminhos diversos.", ["Existência", "Ciência", "Morte", "Corpo", "Poesia"]],
    WS1002: ["Úrsula", "Úrsula e Tancredo se apaixonam em meio a segredos familiares e à violência da escravidão. A narrativa também acompanha Túlio, Susana e outros personagens negros, cujas histórias expõem diferentes experiências de cativeiro e resistência.", "Publicado em 1859 por Maria Firmina dos Reis, Úrsula ocupa lugar pioneiro na literatura abolicionista brasileira e na história do romance escrito por mulheres no país. A narrativa denuncia a escravidão e dá interioridade, memória e voz a personagens negros escravizados, incluindo Túlio e Susana; isso contrasta com muitas representações da época, que os reduziam a tipos ou funções secundárias. A autoria de uma mulher negra também desafia a imagem tradicional de quem podia ser reconhecido como escritor no século XIX.\n\nLer o romance hoje é fundamental para compreender que a crítica à escravidão e a produção literária negra têm história longa no Brasil. Vale pela experiência narrativa e pela perspectiva ética que constrói, sem deixar de notar os limites e convenções românticas de seu tempo. A obra transforma o cânone ao exigir que a história da literatura inclua vozes antes marginalizadas.", ["Escravidão", "Abolicionismo", "Autoria feminina", "Literatura negra", "Memória"]],
};

const slugify = (value) => value.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLocaleLowerCase("pt-BR").replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");

const wikipediaTitles = {
    "affonso-celso": "Affonso Celso de Assis Figueiredo",
    "joao-marques-de-carvalho": "Marques de Carvalho",
    "lima-barreto": "Lima Barreto (escritor)",
    "visconde-de-taunay": "Alfredo d'Escragnolle Taunay",
};
const authors = Object.entries(authorProfiles).map(([id, profile]) => ({
    entityType: "author", entityId: id, title: profile.name, summary: profile.bio,
    editorial: profile.context, themes: [],
    sources: [
        ...(id === "pinto-da-rocha" ? [] : [{ label: "Wikipedia · verbete biográfico", url: `https://pt.wikipedia.org/wiki/${encodeURIComponent((wikipediaTitles[id] || profile.name).replaceAll(" ", "_"))}` }]),
        { label: "Open Library · catálogo de autores", url: `https://openlibrary.org/search/authors?q=${encodeURIComponent(profile.name)}` },
        ...Object.values(readerBooks).filter((book) => slugify(book.author) === id).slice(0, 2).map((book) => ({ label: `Obra em texto integral · ${book.sourceName || "Project Gutenberg"}`, url: book.sourceUrl })),
    ],
}));

const works = Object.values(readerBooks).map((book) => {
    const content = workProfiles[book.workId];
    if (!content) throw new Error(`Editorial copy missing for ${book.workId}`);
    const sourceUrl = book.sourceUrl || (book.gutenbergId ? `https://www.gutenberg.org/ebooks/${book.gutenbergId}` : "");
    const sources = [{ label: `Texto integral · ${book.sourceName || "Project Gutenberg"}`, url: sourceUrl }];
    if (book.workId.startsWith("OL")) sources.push({ label: "Registro bibliográfico · Open Library", url: `https://openlibrary.org/works/${book.workId}` });
    if (book.workId === "OL1003017W") sources.push(
        { label: "Machado de Assis Digital Corpus", url: "https://machado.byu.edu/text/memorias-postumas-de-bras-cubas/" },
        { label: "Edição de 1881 · Biblioteca Brasiliana USP", url: "https://digital.bbm.usp.br/handle/bbm/4826" },
        { label: "SciELO · narrativa e crítica da sociedade escravista", url: "https://www.scielo.br/j/mael/a/WRqgkBNbcMFq3gwYR8Pp3FG/?format=html" },
        { label: "SciELO · experimentação e papel do narrador", url: "https://www.scielo.br/j/mael/a/c43DhyT9jRk33DhNVd9FVBh/?format=pt" },
        { label: "USP · leituras críticas do romance", url: "https://revistas.usp.br/teresa/pt_BR/article/view/116627" },
        { label: "Câmara dos Deputados · Machado e a cultura brasileira", url: "https://www2.camara.leg.br/a-camara/visiteacamara/cultura-na-camara/arquivos/alencar-machado-e-euclides-patrimonios-da-cultura-brasileira" },
    );
    if (book.workId === "OL1003040W") sources.push({ label: "Machado de Assis Digital Corpus", url: "https://machado.byu.edu/text/dom-casmurro/" });
    if (book.workId === "OL1003079W") sources.push({ label: "Machado de Assis Digital Corpus", url: "https://machado.byu.edu/text/quincas-borba/" });
    if (book.workId === "OL1525650W") sources.push({ label: "Biblioteca Brasiliana USP · Iracema", url: "https://brasiliana.usp.br/handle/bbm/4660" });
    if (book.workId === "OL7058886W") sources.push({ label: "FFLCH-USP · O Cortiço", url: "https://www.fflch.usp.br/169955" });
    return {
        entityType: "work", entityId: book.workId, title: content[0] || book.title,
        summary: content[1], editorial: content[2], themes: content[3] || [], sources,
    };
});

export const editorialSeedProfiles = [...authors, ...works];
export const editorialAuthorSlug = slugify;
